"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { createAutocomplete, AutocompleteOptions } from "@algolia/autocomplete-js";
import { algoliasearch, SearchClient, SearchIndex } from "algoliasearch/lite";
import type { AutocompleteRenderer, AutocompleteScopeApi } from "@algolia/autocomplete-core";
import styles from "./SearchAutocomplete.module.css";

export interface Hit {
  objectID: string;
  title: string;
  description?: string;
  image?: string;
  url?: string;
  category?: string;
  [key: string]: unknown;
}

export interface SearchAutocompleteProps {
  appId: string;
  apiKey: string;
  indexName: string;
  placeholder?: string;
  className?: string;
  onSelect?: (hit: Hit) => void;
  getItemUrl?: (hit: Hit) => string;
  renderItem?: (hit: Hit, children: React.ReactNode) => React.ReactNode;
  maxResults?: number;
  detachedMediaQuery?: string;
  openOnFocus?: boolean;
  autoFocus?: boolean;
  initialQuery?: string;
  stallThreshold?: number;
  environment?: string;
}

const DEFAULT_STYLES = `
.aa-dropdownMenu { display: flex; flex-direction: column; gap: 0; }
.aa-item { display: flex; align-items: center; gap: 12px; padding: 12px 16px; text-decoration: none; color: inherit; border-radius: 0; transition: background 0.15s ease; }
.aa-item:hover, .aa-item:focus { background: var(--aa-background-hover, #f5f5f5); outline: none; }
.aa-item__image { width: 48px; height: 48px; object-fit: cover; border-radius: 8px; flex-shrink: 0; }
.aa-item__content { flex: 1; min-width: 0; }
.aa-item__title { font-weight: 600; font-size: 14px; line-height: 1.4; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.aa-item__description { font-size: 13px; color: #666; margin-top: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.aa-item__category { font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; color: #999; background: #f0f0f0; padding: 2px 8px; border-radius: 999px; margin-top: 6px; display: inline-block; }
.aa-source { border-top: 1px solid #eee; }
.aa-source:first-child { border-top: none; }
.aa-sourceHeader { padding: 8px 16px; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; color: #999; }
.aa-empty { padding: 24px 16px; text-align: center; color: #999; font-size: 14px; }
.aa-inputWrapper { position: relative; width: 100%; }
.aa-input { width: 100%; padding: 12px 16px; font-size: 16px; border: 1px solid #ddd; border-radius: 8px; outline: none; transition: border-color 0.15s ease, box-shadow 0.15s ease; background: white; }
.aa-input:focus { border-color: #0066cc; box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.15); }
.aa-input::placeholder { color: #999; }
.aa-submitButton { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); background: none; border: none; cursor: pointer; padding: 4px; color: #999; display: flex; align-items: center; justify-content: center; }
.aa-submitButton:hover { color: #333; }
.aa-loadingIndicator { position: absolute; right: 40px; top: 50%; transform: translateY(-50%); width: 20px; height: 20px; border: 2px solid #eee; border-top-color: #0066cc; border-radius: 50%; animation: aa-spin 0.8s linear infinite; }
@keyframes aa-spin { to { transform: translateY(-50%) rotate(360deg); } }
@media (max-width: 640px) {
  .aa-dropdownMenu { position: fixed !important; left: 0 !important; right: 0 !important; top: 0 !important; bottom: 0 !important; border-radius: 0; max-height: none; overflow-y: auto; z-index: 9999; }
  .aa-panel { max-height: none !important; }
}
`;

export function SearchAutocomplete({
  appId,
  apiKey,
  indexName,
  placeholder = "Search...",
  className = "",
  onSelect,
  getItemUrl,
  renderItem,
  maxResults = 5,
  detachedMediaQuery = "(max-width: 640px)",
  openOnFocus = true,
  autoFocus = false,
  initialQuery = "",
  stallThreshold = 300,
  environment = "production",
}: SearchAutocompleteProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const autocompleteRef = useRef<ReturnType<typeof createAutocomplete<Hit>> | null>(null);
  const [isReady, setIsReady] = useState(false);
  const clientRef = useRef<SearchClient | null>(null);
  const indexRef = useRef<SearchIndex<Hit> | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    clientRef.current = algoliasearch(appId, apiKey);
    indexRef.current = clientRef.current.initIndex<Hit>(indexName);

    const renderer: AutocompleteRenderer<Hit> = {
      render({ children, root }) {
        if (!containerRef.current) return;
        containerRef.current.innerHTML = "";
        containerRef.current.appendChild(children as Node);
      },
    };

    const autocomplete = createAutocomplete<Hit>({
      renderer,
      container: containerRef.current,
      openOnFocus,
      autoFocus,
      initialState: { query: initialQuery },
      stallThreshold,
      environment,
      detachedMediaQuery,
      getSources({ query }) {
        return [
          {
            sourceId: "hits",
            getItems() {
              return indexRef.current!.search<Hit>(query, {
                hitsPerPage: maxResults,
                attributesToHighlight: [],
              }).then(({ hits }) => hits);
            },
            getItemUrl: getItemUrl ?? ((hit) => hit.url ?? `#${hit.objectID}`),
            templates: {
              header: () => <div className={styles.sourceHeader}>Results</div>,
              item({ item, components }) {
                const customRender = renderItem ?? defaultRenderItem;
                return customRender(item, (
                  <a
                    className={styles.item}
                    href={getItemUrl ? getItemUrl(item) : item.url ?? `#${item.objectID}`}
                    onClick={(e) => {
                      e.preventDefault();
                      onSelect?.(item);
                      autocomplete.setIsOpen(false);
                    }}
                  >
                    {item.image && <img className={styles.itemImage} src={item.image} alt="" />}
                    <div className={styles.itemContent}>
                      <div className={styles.itemTitle}>{components.Highlight({ hit: item, attribute: "title" })}</div>
                      {item.description && <div className={styles.itemDescription}>{components.Highlight({ hit: item, attribute: "description" })}</div>}
                      {item.category && <span className={styles.itemCategory}>{item.category}</span>}
                    </div>
                  </a>
                ));
              },
              noResults: () => <div className={styles.empty}>No results found</div>,
              footer: () => null,
            },
          },
        ];
      },
    });

    autocompleteRef.current = autocomplete;
    setIsReady(true);

    const styleEl = document.createElement("style");
    styleEl.textContent = DEFAULT_STYLES;
    document.head.appendChild(styleEl);

    return () => {
      autocomplete.destroy();
      styleEl.remove();
      autocompleteRef.current = null;
      setIsReady(false);
    };
  }, [appId, apiKey, indexName, placeholder, openOnFocus, autoFocus, initialQuery, stallThreshold, environment, detachedMediaQuery, maxResults, onSelect, getItemUrl, renderItem]);

  const setQuery = useCallback((query: string) => {
    autocompleteRef.current?.setQuery(query);
  }, []);

  const open = useCallback(() => {
    autocompleteRef.current?.setIsOpen(true);
  }, []);

  const close = useCallback(() => {
    autocompleteRef.current?.setIsOpen(false);
  }, []);

  return (
    <div
      ref={containerRef}
      className={`${styles.wrapper} ${className}`}
      data-aa-ready={isReady}
    />
  );
}

function defaultRenderItem(hit: Hit, children: React.ReactNode) {
  return children;
}

