import { algoliasearch, SearchClient, SearchIndex } from "algoliasearch/lite";

let searchClient: SearchClient | null = null;

export function getSearchClient(): SearchClient {
  if (!searchClient) {
    const appId = process.env.NEXT_PUBLIC_ALGOLIA_APP_ID;
    const apiKey = process.env.NEXT_PUBLIC_ALGOLIA_SEARCH_API_KEY;

    if (!appId || !apiKey) {
      throw new Error("Missing Algolia credentials. Set NEXT_PUBLIC_ALGOLIA_APP_ID and NEXT_PUBLIC_ALGOLIA_SEARCH_API_KEY");
    }

    searchClient = algoliasearch(appId, apiKey);
  }

  return searchClient;
}

export function getIndex<T = Record<string, unknown>>(indexName: string): SearchIndex<T> {
  return getSearchClient().initIndex<T>(indexName);
}

export async function searchIndex<T = Record<string, unknown>>(
  indexName: string,
  query: string,
  options: Parameters<SearchIndex<T>["search"]>[1] = {}
) {
  const index = getIndex<T>(indexName);
  return index.search<T>(query, {
    hitsPerPage: 10,
    attributesToHighlight: ["title", "description"],
    ...options,
  });
}

